{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.FACT_PARETO_SLAB_PERFORMANCE AS WITH DATE_PARAMS AS ( SELECT DATE_TRUNC(\'MONTH\', CURRENT_DATE()) AS START_DATE, CURRENT_DATE() AS END_DATE ), LATEST_INV_DATE AS ( SELECT COALESCE(MAX(I.DATE), MAX(P.END_DATE)) AS MAX_DATE FROM SNITCH_DB.MAPLEMONK.OFFLINE_MASTER_DAILY_REPORT_1 I CROSS JOIN DATE_PARAMS P WHERE I.DATE <= P.END_DATE ), SKU_CATALOG_PRICES AS ( SELECT UPPER(TRIM(SKU_GROUP)) AS SKU_GROUP, AVG(CAST(PRICE AS NUMBER(10,2))) AS CATALOG_MRP FROM SNITCH_DB.MAPLEMONK.AVAILABILITY_MASTER_V2 WHERE PRICE IS NOT NULL AND PRICE > 0 GROUP BY UPPER(TRIM(SKU_GROUP)) ), INV_SLABS AS ( SELECT I.BRANCH_CODE, COALESCE(M.STORE_NAME, CONCAT(\'STORE_\', I.BRANCH_CODE)) AS STORE_NAME, COALESCE(M.CLUSTER_NAME, \'UNMAPPED_CLUSTER\') AS CLUSTER_NAME, CASE WHEN UPPER(TRIM(I.NEW_CATEGORY)) IN (\'CHINO\', \'CHINOS\', \'TROUSER\', \'TROUSERS\') THEN \'TROUSERS\' WHEN UPPER(TRIM(I.NEW_CATEGORY)) IN (\'DENIM\', \'DENIMS\', \'DEMIN\', \'DEMINS\', \'JEAN\', \'JEANS\') THEN \'JEANS\' ELSE UPPER(TRIM(I.NEW_CATEGORY)) END AS CATEGORY, R.PRICE_SLAB_CODE, R.PRICE_RANGE_LABEL, (COALESCE(I.INVENTORY, 0) + COALESCE(I.JIT_QTY, 0)) AS INV_UNITS FROM SNITCH_DB.MAPLEMONK.OFFLINE_MASTER_DAILY_REPORT_1 I CROSS JOIN LATEST_INV_DATE L LEFT JOIN SKU_CATALOG_PRICES P ON UPPER(TRIM(I.SKU_GROUP)) = P.SKU_GROUP INNER JOIN SNITCH_DB.MAPLEMONK.REF_CATEGORY_PRICE_SLABS R ON ( CASE WHEN UPPER(TRIM(I.NEW_CATEGORY)) IN (\'CHINO\', \'CHINOS\', \'TROUSER\', \'TROUSERS\') THEN \'TROUSERS\' WHEN UPPER(TRIM(I.NEW_CATEGORY)) IN (\'DENIM\', \'DENIMS\', \'DEMIN\', \'DEMINS\', \'JEAN\', \'JEANS\') THEN \'JEANS\' ELSE UPPER(TRIM(I.NEW_CATEGORY)) END ) = R.CATEGORY AND COALESCE(P.CATALOG_MRP, 600) >= R.SLAB_MIN_PRICE AND COALESCE(P.CATALOG_MRP, 600) <= R.SLAB_MAX_PRICE LEFT JOIN SNITCH_DB.MAPLEMONK.STORE_ZONE_MAP M ON CAST(I.BRANCH_CODE AS VARCHAR) = CAST(M.BRANCH_CODE AS VARCHAR) WHERE I.DATE = L.MAX_DATE AND CAST(I.BRANCH_CODE AS VARCHAR) NOT IN (\'2\',\'8\',\'9\',\'10\',\'32\',\'33\',\'35\',\'45\',\'46\',\'59\',\'60\',\'74\',\'76\',\'78\',\'93\',\'94\') ), SALES_SLABS AS ( SELECT S.BRANCH_CODE, COALESCE(M.STORE_NAME, CONCAT(\'STORE_\', S.BRANCH_CODE)) AS STORE_NAME, COALESCE(M.CLUSTER_NAME, \'UNMAPPED_CLUSTER\') AS CLUSTER_NAME, CASE WHEN UPPER(TRIM(S.CATEGORY)) IN (\'CHINO\', \'CHINOS\', \'TROUSER\', \'TROUSERS\') THEN \'TROUSERS\' WHEN UPPER(TRIM(S.CATEGORY)) IN (\'DENIM\', \'DENIMS\', \'DEMIN\', \'DEMINS\', \'JEAN\', \'JEANS\') THEN \'JEANS\' ELSE UPPER(TRIM(S.CATEGORY)) END AS CATEGORY, S.SHIPPING_QUANTITY AS QUANTITY, (S.SHIPPING_QUANTITY * S.SELLING_PRICE) AS REVENUE, R.PRICE_SLAB_CODE, R.PRICE_RANGE_LABEL FROM SNITCH_DB.MAPLEMONK.STORE_FACT_ITEMS_OFFLINE S CROSS JOIN DATE_PARAMS P INNER JOIN SNITCH_DB.MAPLEMONK.REF_CATEGORY_PRICE_SLABS R ON ( CASE WHEN UPPER(TRIM(S.CATEGORY)) IN (\'CHINO\', \'CHINOS\', \'TROUSER\', \'TROUSERS\') THEN \'TROUSERS\' WHEN UPPER(TRIM(S.CATEGORY)) IN (\'DENIM\', \'DENIMS\', \'DEMIN\', \'DEMINS\', \'JEAN\', \'JEANS\') THEN \'JEANS\' ELSE UPPER(TRIM(S.CATEGORY)) END ) = R.CATEGORY AND COALESCE(S.MRP, S.SELLING_PRICE) >= R.SLAB_MIN_PRICE AND COALESCE(S.MRP, S.SELLING_PRICE) <= R.SLAB_MAX_PRICE LEFT JOIN SNITCH_DB.MAPLEMONK.STORE_ZONE_MAP M ON CAST(S.BRANCH_CODE AS VARCHAR) = CAST(M.BRANCH_CODE AS VARCHAR) WHERE LOWER(S.ORDER_STATUS) LIKE \'%process%\' AND S.DOC_PREFIX NOT IN (\'OMS\',\'QCOM\') AND S.ORDER_DATE >= P.START_DATE AND S.ORDER_DATE <= P.END_DATE AND CAST(S.BRANCH_CODE AS VARCHAR) NOT IN (\'2\',\'8\',\'9\',\'10\',\'32\',\'33\',\'35\',\'45\',\'46\',\'59\',\'60\',\'74\',\'76\',\'78\',\'93\',\'94\') ), COMBINED_METRICS AS ( SELECT BRANCH_CODE, STORE_NAME, CLUSTER_NAME, CATEGORY, PRICE_SLAB_CODE, PRICE_RANGE_LABEL, 0 AS INV_UNITS, QUANTITY AS SALES_QTY, REVENUE FROM SALES_SLABS UNION ALL SELECT BRANCH_CODE, STORE_NAME, CLUSTER_NAME, CATEGORY, PRICE_SLAB_CODE, PRICE_RANGE_LABEL, INV_UNITS, 0 AS SALES_QTY, 0 AS REVENUE FROM INV_SLABS ), UNIFIED_AGGREGATE AS ( SELECT \'1. Company Wide\' AS HIERARCHY_LEVEL, \'ALL STORES\' AS LOCATION_ID, \'National (All Stores)\' AS LOCATION_NAME, CATEGORY, PRICE_SLAB_CODE, PRICE_RANGE_LABEL, SUM(INV_UNITS) AS STORE_INV_UNITS, SUM(SALES_QTY) AS SALES_UNITS, SUM(REVENUE) AS SALES_REVENUE FROM COMBINED_METRICS GROUP BY CATEGORY, PRICE_SLAB_CODE, PRICE_RANGE_LABEL UNION ALL SELECT \'2. Cluster Wise\' AS HIERARCHY_LEVEL, CLUSTER_NAME AS LOCATION_ID, CONCAT(CLUSTER_NAME, \' Cluster\') AS LOCATION_NAME, CATEGORY, PRICE_SLAB_CODE, PRICE_RANGE_LABEL, SUM(INV_UNITS) AS STORE_INV_UNITS, SUM(SALES_QTY) AS SALES_UNITS, SUM(REVENUE) AS SALES_REVENUE FROM COMBINED_METRICS GROUP BY CLUSTER_NAME, CATEGORY, PRICE_SLAB_CODE, PRICE_RANGE_LABEL UNION ALL SELECT \'3. Store Wise\' AS HIERARCHY_LEVEL, CAST(BRANCH_CODE AS VARCHAR) AS LOCATION_ID, STORE_NAME AS LOCATION_NAME, CATEGORY, PRICE_SLAB_CODE, PRICE_RANGE_LABEL, SUM(INV_UNITS) AS STORE_INV_UNITS, SUM(SALES_QTY) AS SALES_UNITS, SUM(REVENUE) AS SALES_REVENUE FROM COMBINED_METRICS GROUP BY BRANCH_CODE, STORE_NAME, CATEGORY, PRICE_SLAB_CODE, PRICE_RANGE_LABEL ), PARETO_CALC AS ( SELECT HIERARCHY_LEVEL, LOCATION_ID, LOCATION_NAME, CATEGORY, PRICE_SLAB_CODE, PRICE_RANGE_LABEL, STORE_INV_UNITS, ROUND(100.0 * STORE_INV_UNITS / NULLIF(SUM(STORE_INV_UNITS) OVER (PARTITION BY HIERARCHY_LEVEL, LOCATION_ID, CATEGORY), 0), 2) AS INV_SHARE_PCT, SALES_UNITS, SALES_REVENUE, ROUND(100.0 * SALES_UNITS / NULLIF(SUM(SALES_UNITS) OVER (PARTITION BY HIERARCHY_LEVEL, LOCATION_ID, CATEGORY), 0), 2) AS SALES_SHARE_PCT, SUM(SALES_UNITS) OVER ( PARTITION BY HIERARCHY_LEVEL, LOCATION_ID, CATEGORY ORDER BY SALES_UNITS DESC, PRICE_SLAB_CODE ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) / NULLIF(SUM(SALES_UNITS) OVER (PARTITION BY HIERARCHY_LEVEL, LOCATION_ID, CATEGORY), 0) AS CUMULATIVE_SHARE FROM UNIFIED_AGGREGATE ) SELECT HIERARCHY_LEVEL, LOCATION_ID, LOCATION_NAME, CATEGORY, PRICE_SLAB_CODE, PRICE_RANGE_LABEL, STORE_INV_UNITS, INV_SHARE_PCT, SALES_UNITS, SALES_REVENUE, SALES_SHARE_PCT, ROUND(CUMULATIVE_SHARE * 100, 2) AS CUMULATIVE_SHARE_PCT, CASE WHEN CUMULATIVE_SHARE <= 0.50 THEN \'A\' WHEN CUMULATIVE_SHARE <= 0.80 THEN \'B\' WHEN CUMULATIVE_SHARE <= 0.95 THEN \'C\' ELSE \'D\' END AS PARETO_ABCD_RANK, CURRENT_TIMESTAMP() AS UPDATED_AT FROM PARETO_CALC;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            